-- "Armor & Items" tab of the GM Tool Chest: browse every synced Retail armor set, armor piece, weapon and mount
-- (ToolChestCatalog.lua, generated by Tools/ServerSync/export_toolchest_catalog.py) and click to put it in your bags or
-- learn it. Loaded before ToolChest.lua, which calls EsteriaToolChest_BuildCatalogPage(api) with its widget kit.
--   Sets      left-click adds every piece to your bags, right-click previews the pieces
--   Armor     left-click adds the piece
--   Weapons   left-click adds the weapon
--   Mounts    left-click teaches the mount (.learn), right-click adds the item
-- Everything is a normal GM chat command (.additem / .learn) on yourself or the selected player.

local INV = { [1] = "Head", [2] = "Neck", [3] = "Shoulder", [4] = "Shirt", [5] = "Chest", [6] = "Waist", [7] = "Legs",
    [8] = "Feet", [9] = "Wrist", [10] = "Hands", [11] = "Finger", [12] = "Trinket", [13] = "One-Hand", [14] = "Shield",
    [15] = "Bow", [16] = "Back", [17] = "Two-Hand", [19] = "Tabard", [20] = "Robe", [21] = "Main Hand", [22] = "Off Hand",
    [23] = "Held", [25] = "Thrown", [26] = "Ranged" }
local SLOT_ORDER = { 1, 3, 16, 5, 20, 4, 19, 9, 10, 6, 7, 8, 2, 11, 12, 13, 21, 22, 17, 14, 23, 15, 25, 26 }
local SLOT_RANK = {}
for rank, inv in ipairs(SLOT_ORDER) do SLOT_RANK[inv] = rank end
local ARMOR = { [0] = "Misc", [1] = "Cloth", [2] = "Leather", [3] = "Mail", [4] = "Plate", [6] = "Shield" }
local WEAPON = { [0] = "Axe", [1] = "2H Axe", [2] = "Bow", [3] = "Gun", [4] = "Mace", [5] = "2H Mace", [6] = "Polearm",
    [7] = "Sword", [8] = "2H Sword", [10] = "Staff", [13] = "Fist", [15] = "Dagger", [16] = "Thrown", [18] = "Crossbow",
    [19] = "Wand", [20] = "Fishing Pole" }
local QUALITY = { [0] = { 0.6, 0.6, 0.6 }, { 1, 1, 1 }, { 0.12, 1, 0 }, { 0, 0.44, 0.87 }, { 0.64, 0.21, 0.93 }, { 1, 0.5, 0 },
    { 0.9, 0.8, 0.5 }, { 0.9, 0.8, 0.5 } }
local MAX_SET_ADD = 20      -- bigger groups (PvP season sets) are browsed piece by piece
local SEND_EVERY = 0.15     -- seconds between queued commands, so a whole set never trips the chat throttle

local items, sets, built = {}, {}, false

local function Build()
    if built then return end
    built = true
    for line in string.gmatch(EsteriaToolChestCatalog or "", "[^\n]+") do
        local id, name, class, sub, inv, quality, ilvl, req, spell =
            string.match(line, "^(%d+)|(.-)|(%d+)|(%d+)|(%d+)|(%d+)|(%d+)|(%d+)|(%d+)$")
        if id then
            items[#items + 1] = { id = tonumber(id), name = name, lower = string.lower(name), class = tonumber(class),
                sub = tonumber(sub), inv = tonumber(inv), quality = tonumber(quality), ilvl = tonumber(ilvl),
                req = tonumber(req), spell = tonumber(spell) }
        end
    end
    -- A set is every armor piece sharing the "<Name>'s " prefix. Groups with several armor types (a class-wide set) split
    -- by type so each outfit stays one wearable set.
    local groups = {}
    for _, it in ipairs(items) do
        if it.class == 4 and it.sub >= 1 and it.sub <= 4 then
            local prefix = string.match(it.name, "^(.-)'s ")
            if prefix and prefix ~= "" then
                local g = groups[prefix]
                if not g then g = {}; groups[prefix] = g end
                g[#g + 1] = it
            end
        end
    end
    local function Add(name, pieces)
        if #pieces < 2 then return end
        table.sort(pieces, function(a, b)
            local ra, rb = SLOT_RANK[a.inv] or 99, SLOT_RANK[b.inv] or 99
            if ra ~= rb then return ra < rb end
            return a.id < b.id
        end)
        sets[#sets + 1] = { name = name, lower = string.lower(name), pieces = pieces, quality = pieces[1].quality,
            req = pieces[1].req }
    end
    for prefix, pieces in pairs(groups) do
        if #pieces <= 12 then
            Add(prefix, pieces)
        else
            local byType = {}
            for _, it in ipairs(pieces) do
                byType[it.sub] = byType[it.sub] or {}
                tinsert(byType[it.sub], it)
            end
            for sub, list in pairs(byType) do Add(prefix .. " (" .. (ARMOR[sub] or sub) .. ")", list) end
        end
    end
    table.sort(sets, function(a, b) return a.lower < b.lower end)
end

function EsteriaToolChest_BuildCatalogPage(api)
    local ES, W, H, RAIL = api.ES, api.W, api.H, api.RAIL
    local page = api.AddPage("catalog", "Armor & Items", "every synced Retail set, armor piece, weapon and mount")

    -- Command queue ---------------------------------------------------------------------------------------------
    local queue, clock = {}, 0
    local sender = CreateFrame("Frame")
    sender:Hide()
    sender:SetScript("OnUpdate", function(self, dt)
        clock = clock + dt
        if clock < SEND_EVERY then return end
        clock = 0
        local command = tremove(queue, 1)
        if command then api.Run(command) end
        if #queue == 0 then self:Hide() end
    end)
    local function Queue(commands)
        for _, command in ipairs(commands) do queue[#queue + 1] = command end
        clock = SEND_EVERY
        sender:Show()
    end

    -- State -----------------------------------------------------------------------------------------------------
    local CATEGORIES = { "Sets", "Armor", "Weapons", "Mounts", "All" }
    local category, filterIndex, query = "Sets", 1, ""
    local FILTERS = {
        Armor = { { "All types" }, { "Cloth", function(it) return it.sub == 1 end }, { "Leather", function(it) return it.sub == 2 end },
            { "Mail", function(it) return it.sub == 3 end }, { "Plate", function(it) return it.sub == 4 end },
            { "Shields", function(it) return it.sub == 6 end }, { "Other", function(it) return it.sub == 0 end } },
        Weapons = { { "All weapons" }, { "1H", function(it) return it.inv == 13 or it.inv == 21 or it.inv == 22 end },
            { "2H", function(it) return it.inv == 17 end }, { "Ranged", function(it) return it.inv == 15 or it.inv == 26 or it.inv == 25 end },
            { "Off hand / Held", function(it) return it.inv == 22 or it.inv == 23 or it.inv == 14 end } },
    }
    local results, previewing = {}, nil
    local list, preview, tabs, filterButton, search, header, previewTitle, countText

    local function Quality(it) return QUALITY[it.quality] or QUALITY[1] end

    local function ItemInfo(it)
        local slot = INV[it.inv] or ""
        local kind = it.class == 4 and (ARMOR[it.sub] or "") or it.class == 2 and (WEAPON[it.sub] or "Weapon") or ""
        if it.spell > 0 then return "Mount / pet" end
        if slot ~= "" and kind ~= "" and kind ~= slot then return kind .. " " .. slot end
        return slot ~= "" and slot or kind
    end

    local function Match(it)
        if query ~= "" and not string.find(it.lower, query, 1, true) then return false end
        local filters = FILTERS[category]
        local f = filters and filters[filterIndex]
        return not (f and f[2]) or f[2](it)
    end

    local function Refilter()
        Build()
        results = {}
        if category == "Sets" then
            for _, s in ipairs(sets) do
                if query == "" or string.find(s.lower, query, 1, true) then results[#results + 1] = { set = s } end
            end
        else
            for _, it in ipairs(items) do
                local wanted = category == "All"
                    or (category == "Armor" and it.class == 4)
                    or (category == "Weapons" and it.class == 2)
                    or (category == "Mounts" and it.spell > 0)
                if wanted and Match(it) then results[#results + 1] = { item = it } end
            end
        end
        list:Set(results)
        countText:SetText(#results .. (category == "Sets" and " sets" or " items"))
        if FILTERS[category] then filterButton:Show() else filterButton:Hide() end
        if FILTERS[category] then filterButton.label:SetText(FILTERS[category][filterIndex][1]) end
    end

    local function SetCategory(name)
        category, filterIndex = name, 1
        for _, t in ipairs(tabs) do
            local on = t.name == name
            local c = on and ES.GOLD or ES.MUTED
            t.label:SetTextColor(c[1], c[2], c[3])
            if on then t.underline:Show() else t.underline:Hide() end
        end
        Refilter()
    end

    -- Actions ---------------------------------------------------------------------------------------------------
    local function AddItem(it)
        Queue({ "additem " .. it.id })
        api.Status("Adding " .. it.name .. " (" .. it.id .. ")", ES.GOOD)
    end

    local function Learn(it)
        Queue({ "learn " .. it.spell })
        api.Status("Teaching " .. it.name .. " (spell " .. it.spell .. ")", ES.GOOD)
    end

    local function AddSet(set)
        if #set.pieces > MAX_SET_ADD then
            api.Status(set.name .. " has " .. #set.pieces .. " pieces: right-click it, then click the pieces you want.", ES.BAD)
            return
        end
        local commands = {}
        for _, it in ipairs(set.pieces) do commands[#commands + 1] = "additem " .. it.id end
        Queue(commands)
        api.Status("Adding " .. #set.pieces .. " pieces of " .. set.name .. " to your bags", ES.GOOD)
    end

    local function Preview(set)
        previewing = set
        previewTitle:SetText(set and (set.name .. "  |cff9a9a9a(" .. #set.pieces .. ")|r") or "Preview")
        preview:Set(set and set.pieces or {})
    end

    local function Tooltip(row, entry)
        GameTooltip:SetOwner(row, "ANCHOR_RIGHT")
        if entry.set then
            GameTooltip:AddLine(entry.set.name, 1, 0.82, 0)
            for _, it in ipairs(entry.set.pieces) do
                local q = Quality(it)
                GameTooltip:AddDoubleLine(it.name, INV[it.inv] or "", q[1], q[2], q[3], 0.7, 0.7, 0.7)
            end
        else
            local it = entry.item
            GameTooltip:SetHyperlink("item:" .. it.id)
            if not GameTooltip:IsShown() then
                local q = Quality(it)
                GameTooltip:ClearLines()
                GameTooltip:AddLine(it.name, q[1], q[2], q[3])
                GameTooltip:AddLine(ItemInfo(it), 0.7, 0.7, 0.7)
            end
            GameTooltip:AddLine("Item " .. it.id .. ", level " .. it.ilvl, 0.6, 0.6, 0.6)
        end
        GameTooltip:Show()
    end

    -- Layout ----------------------------------------------------------------------------------------------------
    local LEFT_W = 478
    local ROWS = 17
    local RIGHT_X = LEFT_W + 18
    local RIGHT_W = W - RAIL - 36 - RIGHT_X

    tabs = {}
    local x = 0
    for _, name in ipairs(CATEGORIES) do
        local b = CreateFrame("Button", nil, page)
        b:SetSize(math.max(54, #name * 9 + 18), 24)
        b:SetPoint("TOPLEFT", x, 0)
        b.name = name
        b.label = ES.Text(b, 13, ES.MUTED)
        b.label:SetPoint("CENTER")
        b.label:SetText(name)
        b.underline = ES.Solid(b, "ARTWORK", ES.GOLD, 1)
        b.underline:ClearAllPoints()
        b.underline:SetPoint("BOTTOMLEFT")
        b.underline:SetPoint("BOTTOMRIGHT")
        b.underline:SetHeight(2)
        b.underline:Hide()
        ES.Solid(b, "HIGHLIGHT", ES.GOLD, 0.1):SetAllPoints()
        b:SetScript("OnClick", function() SetCategory(name) end)
        tabs[#tabs + 1] = b
        x = x + b:GetWidth() + 4
    end

    search = api.Input(page, 250, nil, function(self)
        query = string.lower(self:GetText() or "")
        Refilter()
    end)
    search:SetPoint("TOPLEFT", 0, -32)
    local hint = ES.Text(page, 10, ES.MUTED)
    hint:SetPoint("LEFT", search, "RIGHT", 8, 0)
    hint:SetText("search by name")
    filterButton = api.Button(page, "All types", 120, function()
        local filters = FILTERS[category]
        if not filters then return end
        filterIndex = filterIndex % #filters + 1
        Refilter()
    end)
    filterButton:SetPoint("TOPLEFT", 258, -32)
    countText = ES.Text(page, 11, ES.MUTED)
    countText:SetPoint("TOPRIGHT", page, "TOPLEFT", LEFT_W, -37)
    countText:SetJustifyH("RIGHT")

    list = api.List(page, LEFT_W, ROWS, function(host, w)
        local r = CreateFrame("Button", nil, host)
        r:SetSize(w, api.ROW_H)
        r:RegisterForClicks("LeftButtonUp", "RightButtonUp")
        ES.Solid(r, "BACKGROUND", ES.GOLD_DIM, 0.08):SetAllPoints()
        ES.Solid(r, "HIGHLIGHT", ES.GOLD, 0.12):SetAllPoints()
        r.left = ES.Text(r, 11, ES.TEXT)
        r.left:SetPoint("LEFT", 8, 0)
        r.left:SetPoint("RIGHT", -120, 0)
        r.left:SetJustifyH("LEFT")
        r.right = ES.Text(r, 10, ES.MUTED)
        r.right:SetPoint("RIGHT", -8, 0)
        r:SetScript("OnClick", function(self, button)
            local entry = self.item
            if not entry then return end
            if entry.set then
                if button == "RightButton" then Preview(entry.set) else AddSet(entry.set); Preview(entry.set) end
            elseif entry.item.spell > 0 and button ~= "RightButton" then
                Learn(entry.item)
            else
                AddItem(entry.item)
            end
        end)
        r:SetScript("OnEnter", function(self) if self.item then Tooltip(self, self.item) end end)
        r:SetScript("OnLeave", function() GameTooltip:Hide() end)
        return r
    end, function(r, entry)
        if entry.set then
            local q = QUALITY[entry.set.quality] or QUALITY[1]
            r.left:SetText(entry.set.name)
            r.left:SetTextColor(q[1], q[2], q[3])
            r.right:SetText(#entry.set.pieces .. " pieces")
        else
            local it = entry.item
            local q = Quality(it)
            r.left:SetText(it.name)
            r.left:SetTextColor(q[1], q[2], q[3])
            r.right:SetText(ItemInfo(it))
        end
    end)
    list.host:SetPoint("TOPLEFT", 0, -64)

    previewTitle = ES.Text(page, 13, ES.GOLD)
    previewTitle:SetPoint("TOPLEFT", RIGHT_X, -37)
    previewTitle:SetText("Preview")
    previewTitle:SetWidth(RIGHT_W)
    previewTitle:SetJustifyH("LEFT")
    preview = api.List(page, RIGHT_W, ROWS - 1, function(host, w)
        local r = CreateFrame("Button", nil, host)
        r:SetSize(w, api.ROW_H)
        ES.Solid(r, "BACKGROUND", ES.GOLD_DIM, 0.08):SetAllPoints()
        ES.Solid(r, "HIGHLIGHT", ES.GOLD, 0.12):SetAllPoints()
        r.left = ES.Text(r, 11, ES.TEXT)
        r.left:SetPoint("LEFT", 8, 0)
        r.left:SetPoint("RIGHT", -62, 0)
        r.left:SetJustifyH("LEFT")
        r.right = ES.Text(r, 10, ES.MUTED)
        r.right:SetPoint("RIGHT", -6, 0)
        r:SetScript("OnClick", function(self) if self.item then AddItem(self.item) end end)
        r:SetScript("OnEnter", function(self) if self.item then Tooltip(self, { item = self.item }) end end)
        r:SetScript("OnLeave", function() GameTooltip:Hide() end)
        return r
    end, function(r, it)
        local q = Quality(it)
        r.left:SetText(it.name)
        r.left:SetTextColor(q[1], q[2], q[3])
        r.right:SetText(INV[it.inv] or "")
    end)
    preview.host:SetPoint("TOPLEFT", RIGHT_X, -64)
    local addAll = api.Button(page, "Add whole set", RIGHT_W, function()
        if previewing then AddSet(previewing) else api.Status("Right-click a set to preview it first.", ES.BAD) end
    end)
    addAll:SetPoint("TOPLEFT", RIGHT_X, -64 - (ROWS - 1) * (api.ROW_H + 2) - 6)

    local help = ES.Text(page, 10, ES.MUTED)
    help:SetPoint("BOTTOMLEFT", 0, 2)
    help:SetWidth(W - RAIL - 36)
    help:SetJustifyH("LEFT")
    help:SetText("Click to add to your bags (or to the selected player's). Sets: right-click previews. Mounts: click teaches, right-click adds the item.")

    page.OnOpen = function()
        Build()
        SetCategory(category)
    end
end
